import { readFileSync } from "node:fs";
import { join } from "node:path";
import { emit, packageDir, packageInfo } from "./lib.mjs";

const dir = join(packageDir("@fontsource/inter"), "files");
const b64 = (weight) =>
  readFileSync(join(dir, `inter-latin-${weight}-normal.woff2`)).toString("base64");
const version = packageInfo("@fontsource/inter").version;

const out = `// SPDX-License-Identifier: Apache-2.0
// Generated by scripts/gen-font.mjs from @fontsource/inter ${version}. Do not edit.
//
// Inter, SIL Open Font License 1.1, Copyright 2016 The Inter Project Authors.
// See THIRD_PARTY_NOTICES.md.

export const INTER_400_WOFF2_BASE64 = "${b64(400)}";
export const INTER_600_WOFF2_BASE64 = "${b64(600)}";
`;

emit("src/render/generated/font.ts", out);
